selector::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(270deg, rgba(32,14,22,.86) 0%, rgba(32,14,22,.55) 38%, rgba(32,14,22,.08) 62%, transparent 78%);
  z-index: 0;
}
selector .e-con-inner { position: relative; z-index: 1; }

selector .ue-grid-item-meta-data{
    background: rgba(255,255,255,0.75);
    color: #6B2CBF !important;
    padding: 4px 8px;
    border-radius: 4px;
    width: fit-content;
}
selector .ue-grid-item{transition:transform .4s cubic-bezier(.22,1,.36,1),box-shadow .4s ease;}
selector .ue-grid-item:hover{transform:translateY(-8px);box-shadow:0 18px 36px rgba(80,30,40,.16);}
selector .ue-grid-item img{transition:transform .6s ease;}
selector .ue-grid-item:hover img{transform:scale(1.06);}

